def solve(inp):
    from collections import Counter
    H,W=len(inp),len(inp[0])
    sepc=Counter(x for r in inp for x in r if x).most_common(1)[0][0]
    rowbands=[]; prev=0
    for i in range(H):
        if all(x==sepc for x in inp[i]): prev=i+1
        elif prev<i: pass
    # detect separator rows/cols
    seprows=[i for i in range(H) if all(inp[i][j]==sepc for j in range(W))]
    sepcols=[j for j in range(W) if all(inp[i][j]==sepc for i in range(H))]
    rb=[]; p=0
    for r in seprows+[H]:
        if r>p: rb.append((p,r)); p=r+1
    cb=[]; p=0
    for c in sepcols+[W]:
        if c>p: cb.append((p,c)); p=c+1
    # find shapes per band
    shapes={}
    for ri,(a,b) in enumerate(rb):
        for ci,(d,e) in enumerate(cb):
            cells={}
            for i in range(a,b):
                for j in range(d,e):
                    v=inp[i][j]
                    if v!=sep and v!=0: cells.setdefault(v,[]).append((i-a,j-d))
            if len(cells)==1 and len(next(iter(cells.values())))==4 and 4>=len(set(zip(*next(iter(cells.values()))))):
                pass
            # rectangle test: exactly 4 cells forming solid 2x2
            vals=list(cells.values())[0]
            isrect = len(vals)==4 and max(r for r,_ in vals)-min(r for r,_ in vals)==1 and max(c for _,c in vals)-min(c for _,c in vals)==1
            shapes[(ri,ci)]=(isrect,list(cells)[0] if isrect else None)
    # irregular shapes (non-rect)
    irr=[((ri,ci),sorted(cs)) for (ri,ci),(isrect,cs) in shapes.items() if not isrect and cs]
    # special = largest
    irr.sort(key=lambda x:-len(x[1]))
    spec=irr[0][1]
    sr=min(r for r,_ in spec); sc=min(c for _,c in spec)
    shp=[[0]*4 for _ in range(4)]
    for r,c in spec: shp[r-sr][c-sc]=1
    out=[row[:] for row in inp]
    # erase all shapes
    for ri,(a,b) in enumerate(rb):
        for ci,(d,e) in enumerate(cb):
            for i in range(a,b):
                for j in range(d,e):
                    if inp[i][j] not in (0,sepc): out[i][j]=0
    # stamp color: leftmost rect color in row band
    for ri,(a,b) in enumerate(rb):
        for ci,(d,e) in enumerate(cb):
            cands=[shapes[(ri,cj)][1] for cj in range(len(cb)) if shapes[(ri,cj)][0] and shapes[(ri,cj)][1]]
            color=None
            for cs in cands:
                rs=[r for r,_ in cs]; cls=[c for _,c in cs]
                if max(rs)-min(rs)==1 and max(cls)-min(cls)==1:
                    color=inp[a+rs[0]][d+cls[0]]
            if color is None: continue
            for i,r in enumerate(range(4)):
                for j,c in enumerate(range(4)):
                    if shp[r][c]: out[a+i][d+j]=color
    return out
