    for i in range(H):
        for j in range(W):
            if mask[i,j] and lab[i,j]<0:
                cid+=1; q=[(i,j)]; lab[i,j]=cid; cc=[]
                while q:
                    a,b=q.pop(); cc.append((a,b))
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+di,b+dj
                        if 0<=x<H and 0<=y<W and mask[x,y] and lab[x,y]<0:
                            lab[x,y]=cid; q.append((x,y))
                ys=[a for a,_ in cc]; xs=[b for _,b in cc]
                info.append(dict(id=cid,color=int(inp[cc[0][0],cc[0][1]]),
                                 bbox=(min(ys),max(ys),min(xs),max(xs)),cells=set(cc)))
    # key object = largest component
    key=max(info,key=lambda o:o['size'])
    keypat=np.zeros((key['bbox'][1]-key['bbox'][0]+1,key['bbox'][3]-key['bbox'][2]+1),int)
    for a,b in key['cells']:
        keypat[a-key['bbox'][0],b-key['bbox'][2]]=1
    # band lattice from separators
    rb=[-1]+rows+[H-1]; cb=[-1]+cols+[W-1]
    def band_idx(val,seps,n):
        # find band start: previous separator index
        idx=n-1
        while idx>=0 and seps[idx]!=val: idx-=1
        return idx  # separator index before val
    ridx=[band_idx(r,rows,H) for r in range(H)]
    cidx=[band_idx(c,cols,W) for c in range(W)]
    # offset from key's band
    kr=key['bbox'][0]; kc=key['bbox'][2]
    # find nearest preceding separator
    def bandstart(seps,val,n):
        s=-1
        for k in range(n-1,-1,-1):
            if seps[k]==val: s=k; break
        return s+1
    br=bandstart(rows,kr,len(rows)); bc=bandstart(cols,kc,len(cols))
    off=(kr-br, kc-bc)
    out=inp.copy()
    # stamp color per band cell: normal object color in same row-band or col-band
    nobj=[o for o in info if o not in [key]]
    obj_by_band_r={}  # band_index -> set of colors
    for o in nobj:
        si=bandstart(rows,o['bbox'][0],len(rows)); sj=bandstart(cols,o['bbox'][2],len(cols))
        obj_by_band_r.setdefault(si,set()).add(o['color'])
        obj_by_band_c.setdefault(sj,set()).add(o['color'])
    stamps={}
    for i in range(H):
