            ri=ridx[i]; ci=cdx[j] if False else None
    # redo cleanly: map each cell to its (rowband, colband)
    rowband=[None]*H; colband=[None]*W
    cur=0
    for idx,s in enumerate(rows):
        for k in range(cur,idx+1): rowband[k]=cur
        cur=s+1
    cur=0
    for idx,s in enumerate(cols):
        for k in range(cur,idx+1): colband[k]=cur
        cur=s+1
    # unique band ids
    rbset=sorted({rb}) ; cbset=sorted({cb})
    def get_color(rbc):
        s=obj_by_band_r.get(rbc,obj_by_band_c.get(cbc,set()))
        return s.popleft() if False else (list(s)[0] if len(s)==1 else None)
    # determine stamp color per (rowband,colband): prefer rowband color if any normal obj in that rowband, else colband
    rcmap={}
    for i in range(H):
        for j in range(W):
            rb_=rowband[i]; cb_=colband[j]
            cand=obj_by_band_r.get(rb_) or obj_by_band_c.get(cb_)
            rcmap[(rb_,cb_)]=list(cand)[0] if cand else None
    for (rb,cb),col in rcmap.items():
        if col is None: continue
        rs=[k for k,v in [(x,rowband.index(v)) for v in [None]]]  # placeholder
        # actual row indices in this rowband
        rows_i=[i for i,r in enumerate(rowband) if r==rb]
        cols_j=[j for j,c in enumerate(colband) if c==cb]
        for a in rows_i:
            for b in cols_j:
                for da in range(keypat.shape[0]):
                    for db in range(keypat.shape[1]):
                        if keypat[da,db]:
