    info=defaultdict(list)
    for i in range(H):
        for j in range(W):
            if not sepv[i,j] and inp[i,j]!=0 and inp[i,j]!=sepc:
                info[int(inp[i,j])].append((i,j))
    spec=max(info,key=lambda v:len(info[v]))
    cells=[(i,j) for i,j in info[spec]]
    stamp=np.zeros((max(i for i,_ in cells)-min(i for i,_ in cells)+1, max(j for _,j in cells)-min(j for _,j in cells)+1),int)
    for a,b in cells: stamp[a-min(i for i,_ in cells), b-min(j for _,j in cells)]=1
    bands={}
    for v,cells_ in info.items():
        if v==spec: continue
        rb=min(i for i,_ in cells_)
        bands.setdefault(rb,set()).add(v)
    out=inp.copy()
    # row blocks: consecutive rows between separator rows (inclusive of the sep block?)
    # each band = band of non-sep rows; stamp placed at top-left of every column-group within that band's first row? observe demo1 band row2-3 -> placed at band-top-left corner row.
    for i in range(H):
        if i in sr: continue
