def shapes(g, bg=set()):
    res=[]
    seen=[[False]*len(g[0]) for _ in g]
    for a in range(len(g)):
        for b in range(len(g[0])):
            if g[a][b]!=0 and not seen[a][b]:
                col=g[a][b]; stack=[(a,b)]; cells=[]
                while stack:
                    y,x=stack.pop()
                    if 0<=y<len(g) and 0<=x<len(g[0]) and not seen[y][x] and g[y][x]==col:
                        seen[y][x]=True; cells.append((y,x))
                        stack+= [(y+1,x),(y-1,x),(y,x+1),(y,x-1)]
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                res.append((col,len(cells),min(ys),min(xs),max(ys),max(xs)))
