def comps(g,val):
    seen=set(); res=[]
    H,W=len(g),len(g[0])
    for a in range(H):
        for b in range(W):
            if g[a][b]==val and (a,b) not in seen:
                st=[(a,b)]; seen.add((a,b)); c=[]
                while st:
                    r,c_=(st.pop()); c.append((r,c_))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=r+dr,c_+dc
                        if 0<=x<H and 0<=y<W and g[x][y]==val and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                res.append(c)
    return res
